Image.style:
width: 100%;
height: 100%;
margin: 0px;
border-radius: 5px;
object-fit: cover;
object-position: 50% 50%;
position: absolute;
z-index: 0;
left: 0px;
top: 0px;
transform: none;
mask-image: url({{alphaBase64}});
mask-size: cover;
-webkit-mask-image: url({{alphaBase64}});
-webkit-mask-size: cover;
